      "proposed_laureates": [
        "Peter W. Shor",
        "Andrew M. Steane",
        "Alexei Kitaev"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed that quantum information can be protected from noise and made fault-tolerant computation possible in principle. It is a foundational conceptual advance with broad impact.",
        "attribution": "Shor and Steane independently introduced important early quantum codes; Kitaev made major contributions to fault tolerance and topological code ideas. The selected names represent distinct, pivotal advances.",
        "maturity": "The theory is mature and experimental demonstrations of error correction have advanced substantially, though large-scale fault-tolerant operation remains an active goal.",
        "uncertainties": [
          "The ultimate practical reach of fault-tolerant quantum computing remains unsettled."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B035",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "Sajeev John",
        "John D. Joannopoulos"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic crystals established how periodic structures can control light propagation, including the possibility of photonic band gaps. The idea opened a major field at the intersection of wave physics and materials.",
        "attribution": "Yablonovitch and John independently introduced the key photonic band-gap concept; Joannopoulos helped develop its theoretical foundations and broader reach.",
        "maturity": "The concept has been experimentally realized and supports a mature body of research and applications.",
        "uncertainties": [
          "The distinction between the original proposals and the subsequent development of the field should guide credit."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold atoms in optical lattices provide unusually clean, controllable quantum simulators and enabled direct study of important lattice models, including strongly interacting regimes.",
        "attribution": "Zoller helped establish the theoretical vision; Bloch and Greiner were central to experimental realization and landmark demonstrations. These roles are complementary.",
        "maturity": "The platform is well established and has produced extensive experimental results, while its use to answer some central many-body questions continues to develop.",
        "uncertainties": [
          "The achievement spans a platform and many experiments, so the prize-worthy defining result is not singular."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B031",
